/**
 * AIEventTypes - Central registry for AI event type constants
 *
 * Provides typed constants for all built-in AI events. Using these constants
 * instead of hardcoded strings enables IDE autocompletion, prevents typos,
 * and makes event types discoverable.
 *
 * **Usage**
 *
 * ```js
 * import { AIEvent } from '@three-blocks/pro';
 *
 * // Listen using constants
 * body.ai.addEventListener(AIEvent.FIRE, (event) => {
 *   createMuzzleFlash(event.origin);
 * });
 *
 * body.ai.addEventListener(AIEvent.INTENT_CHANGE, (event) => {
 *   console.log(`Intent changed: ${event.previous} → ${event.current}`);
 * });
 * ```
 *
 * **Custom Events**
 *
 * Custom intents/sensors can emit any string event type. Built-in events
 * use lowercase names to avoid collisions with user-defined events.
 *
 * ```js
 * // In custom intent
 * this.emit('myCustomEvent', { data: 'value' });
 *
 * // Listen to custom event
 * body.ai.addEventListener('myCustomEvent', handler);
 * ```
 *
 * @module @three-blocks/pro/ai/AIEventTypes
 * @short Central AI event type registry
 * @category AI
 * @tags AI, Events, Constants
 */
/**
 * Emitted when the active intent changes.
 * @type {string}
 * @event intentChange
 * @property {string} previous - Previous intent type or 'idle'
 * @property {string} current - New intent type or 'idle'
 */
export const INTENT_CHANGE: string;
/**
 * Emitted when EngageIntent activates (combat starts).
 * @type {string}
 * @event engage
 * @property {Object} targetPosition - Target position { x, y, z }
 * @property {number} targetDistance - Distance to target
 */
export const ENGAGE: string;
/**
 * Emitted when PatrolIntent activates.
 * @type {string}
 * @event patrol
 * @property {number} waypointIndex - Current waypoint index
 * @property {Object} waypoint - Current waypoint { x, y, z }
 */
export const PATROL: string;
/**
 * Emitted when PatrolIntent reaches a waypoint.
 * @type {string}
 * @event waypointReached
 * @property {number} waypointIndex - Reached waypoint index
 * @property {Object} waypoint - Waypoint position { x, y, z }
 * @property {boolean} isLast - True if this is the last waypoint
 */
export const WAYPOINT_REACHED: string;
/**
 * Emitted when an AI agent fires a weapon.
 * @type {string}
 * @event fire
 * @property {Object} origin - Fire origin position { x, y, z }
 * @property {Object} direction - Fire direction vector { x, y, z }
 * @property {Object} target - Target position { x, y, z }
 */
export const FIRE: string;
/**
 * Emitted when VisionSensor acquires a new target.
 * @type {string}
 * @event targetAcquired
 * @property {number} targetIndex - Target body index
 * @property {string} targetType - Target body type
 * @property {number} distance - Distance to target
 * @property {Object} position - Target position { x, y, z }
 */
export const TARGET_ACQUIRED: string;
/**
 * Emitted when VisionSensor loses sight of target.
 * @type {string}
 * @event targetLost
 * @property {Object} lastPosition - Last known target position { x, y, z }
 */
export const TARGET_LOST: string;
/**
 * Emitted when DamageSensor records damage.
 * @type {string}
 * @event damaged
 * @property {number} damage - Damage amount
 * @property {Object|null} direction - Direction damage came from { x, y, z }
 * @property {number|null} shooterIndex - Shooter body index
 * @property {string|null} shooterType - Shooter body type
 */
export const DAMAGED: string;
/**
 * Emitted when AI is enabled on an agent.
 * @type {string}
 * @event enabled
 */
export const ENABLED: string;
/**
 * Emitted when AI is disabled on an agent.
 * @type {string}
 * @event disabled
 */
export const DISABLED: string;
export namespace AIEvent {
    export { INTENT_CHANGE };
    export { ENGAGE };
    export { PATROL };
    export { WAYPOINT_REACHED };
    export { FIRE };
    export { TARGET_ACQUIRED };
    export { TARGET_LOST };
    export { DAMAGED };
    export { ENABLED };
    export { DISABLED };
}
/**
 * Intent events grouped for documentation.
 * @type {Object}
 */
export const IntentEvents: any;
/**
 * Action events grouped for documentation.
 * @type {Object}
 */
export const ActionEvents: any;
/**
 * Sensor events grouped for documentation.
 * @type {Object}
 */
export const SensorEvents: any;
/**
 * State events grouped for documentation.
 * @type {Object}
 */
export const StateEvents: any;
